def transform(grid):
    h, w = len(grid), len(grid[0])
    if h % 2 and len(set(grid[h // 2])) == 1:
        a, b = grid[:h // 2], grid[h // 2 + 1:]
    elif w % 2 and len({grid[i][w // 2] for i in range(h)}) == 1:
        k = w // 2
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]
    else:
        raise ValueError("no central divider")

    common = set(value for row in a for value in row) & set(
        value for row in b for value in row
    )
    color = next(iter(common))
    return [
        [3 if a[i][j] == color and b[i][j] == color else color
         for j in range(len(a[0]))]
        for i in range(len(a))
    ]

